// HTTP
route POST /orders (req) {
  input = parsePlaceOrderBody(req.body)      // формат проверяет адаптер
  order = await placeOrder(input)
  return http(201, toJson(order))
}

// очередь
on message "order.requested" (msg) {
  await placeOrder(fromMessage(msg))
}

// плохо: ядро говорит на языке библиотеки
interface Mailer { sendSmtp(host, port, from, to, mime) }

// хорошо: ядро говорит на своём языке
interface CustomerNotifier { orderReady(customerId, orderId): Promise<void> }
